<?php
require __DIR__.'/ui.php';role(['admin','gerente']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_POST['settings'])){set_setting('loyalty_spend_per_point',$_POST['ratio']);set_setting('loyalty_point_value',$_POST['point_value']);}else{$p->prepare("INSERT INTO coupons(code,type,value,expiry_date,active)VALUES(?,?,?,?,1)")->execute([strtoupper(trim($_POST['code'])),$_POST['type'],$_POST['value'],$_POST['expiry_date']?:null]);}go('loyalty.php');}$customers=$p->query("SELECT name,points FROM customers ORDER BY points DESC")->fetchAll();$coupons=$p->query("SELECT * FROM coupons ORDER BY id DESC")->fetchAll();page_head('Fidelidade / Cupons');?>
<div class="grid g2"><div class="card"><h2>Regra de pontos</h2><form method="post"><?=csrf_field()?><input type="hidden" name="settings" value="1"><label>R$ gastos para 1 ponto</label><input name="ratio" value="<?=e(setting('loyalty_spend_per_point','10'))?>"><label>Valor equivalente de 1 ponto</label><input name="point_value" value="<?=e(setting('loyalty_point_value','0.50'))?>"><button class="primary">Salvar regra</button></form></div><div class="card"><h2>Novo cupom</h2><form method="post"><?=csrf_field()?><label>Código</label><input name="code"><label>Tipo</label><select name="type"><option value="percentual">Percentual</option><option value="fixo">Valor fixo</option></select><label>Valor</label><input type="number" step=".01" name="value"><label>Validade</label><input type="date" name="expiry_date"><button class="primary">Criar cupom</button></form></div></div>
<div class="grid g2"><div class="card"><h2>Ranking de fidelidade</h2><?php foreach(array_slice($customers,0,15) as $c):?><p><?=e($c['name'])?> — <b><?=$c['points']?> pontos</b></p><?php endforeach;?></div><div class="card"><h2>Cupons</h2><?php foreach($coupons as $c):?><p><b><?=e($c['code'])?></b> — <?=$c['type']==='percentual'?$c['value'].'%':money($c['value'])?> — <?=e($c['expiry_date'])?></p><?php endforeach;?></div></div><?php page_foot();?>